using System.ComponentModel.DataAnnotations;
namespace RaceDay.Mvc.Models;
public class RegisterVm { [Required, StringLength(100)] public string FullName {get;set;}=""; [Required,EmailAddress] public string Email {get;set;}=""; [Required,StringLength(100,MinimumLength=6)] public string Password {get;set;}=""; [Required] public string Role {get;set;}="Participant"; }
public class LoginVm { [Required,EmailAddress] public string Email {get;set;}=""; [Required] public string Password {get;set;}=""; }
public class EventVm { public int? EventId {get;set;} [Required,StringLength(100)] public string EventName {get;set;}=""; [StringLength(500)] public string? Description {get;set;} [Required] public DateTime EventDate {get;set;}=DateTime.Now.AddDays(14); [Required,StringLength(150)] public string Location {get;set;}=""; [Range(0.01,999.99)] public decimal DistanceKm {get;set;}=5; [Required] public string EventType {get;set;}="Run"; public IFormFile? BannerImage {get;set;} }
public class CategoryVm { [Required,StringLength(50)] public string CategoryName {get;set;}=""; [Range(0,120)] public int? MinAge {get;set;} [Range(0,120)] public int? MaxAge {get;set;} }
public class ResultVm { [Required] public string FinishTime {get;set;}="00:00:00"; [Range(1,int.MaxValue)] public int FinishPosition {get;set;}=1; }
public class EventEnrolmentsVm { public int EventId {get;set;} public List<EnrolmentDto> Enrolments {get;set;}=new(); public Dictionary<int,ResultDto> ResultsByEnrolment {get;set;}=new(); }
public class ProfileVm { [Required,StringLength(100)] public string FullName {get;set;}=""; [Required,EmailAddress,StringLength(100)] public string Email {get;set;}=""; public IFormFile? ProfileImage {get;set;} public string? ProfileImageUrl {get;set;} }
public class UserDto { public int UserId {get;set;} public string FullName {get;set;}=""; public string Email {get;set;}=""; public string Role {get;set;}=""; public string? ProfileImageUrl {get;set;} }
public class EventDto { public int EventId {get;set;} public int OrganiserId {get;set;} public string OrganiserName {get;set;}=""; public string EventName {get;set;}=""; public string? Description {get;set;} public DateTime EventDate {get;set;} public DateTime CreatedDate {get;set;} public string Location {get;set;}=""; public decimal DistanceKm {get;set;} public string EventType {get;set;}="Run"; public string? BannerImageUrl {get;set;} }
public class CategoryDto { public int CategoryId {get;set;} public int EventId {get;set;} public string CategoryName {get;set;}=""; public int? MinAge {get;set;} public int? MaxAge {get;set;} }
public class EnrolmentDto { public int EnrolmentId {get;set;} public int ParticipantId {get;set;} public string ParticipantName {get;set;}=""; public int EventId {get;set;} public string EventName {get;set;}=""; public int CategoryId {get;set;} public string CategoryName {get;set;}=""; public DateTime EnrolmentDate {get;set;} public string Status {get;set;}="Confirmed"; }
public class ResultDto { public int ResultId {get;set;} public int EnrolmentId {get;set;} public int EventId {get;set;} public string EventName {get;set;}=""; public DateTime EventDate {get;set;} public int ParticipantId {get;set;} public string ParticipantName {get;set;}=""; public string CategoryName {get;set;}=""; public TimeSpan? FinishTime {get;set;} public int? FinishPosition {get;set;} }
